insert into public.collections (slug, name, dye_thai, dye_english, dye_note, theme, summary, description, art, accent_base, accent_text, status, status_note, swatch, motif, i18n, sort)
values ('indigo', 'INDIGO', 'คราม', 'indigo', 'Indigo leaves ferment into a dark vat. Cloth comes out yellow-green and turns blue as it meets the air.', 'Shadow work', 'Meet the feelings you hide and the patterns you keep repeating, one question a night.', array['INDIGO is the first Khram journal, and the dye the studio is named after.', 'Three Acts move from noticing, to understanding, to growing: The Deep Night, The Still Water and The First Light. Every prompt page is followed by a full page to write on.']::text[], 'A full moon over a still lake, with one pale-blue butterfly.', '#80B2DB', '#80B2DB', 'available', 'Available now', '{"src":"/images/swatches/indigo.webp","alt":"Cotton cloth dyed deep indigo, darker where the dye pooled.","width":900,"height":1125}'::jsonb, 'butterfly-moon', '{"th":{"dyeNote":"ใบครามหมักจนกลายเป็นหม้อย้อมสีเข้ม ผ้าที่ยกขึ้นมาเป็นสีเหลืองอมเขียว แล้วกลายเป็นสีน้ำเงินเมื่อเจออากาศ","theme":"สำรวจด้านมืดในใจ (Shadow work)","summary":"ทำความรู้จักความรู้สึกที่ซ่อนไว้ และรูปแบบเดิมๆ ที่เราทำซ้ำ คืนละหนึ่งคำถาม","description":["INDIGO คือสมุดเล่มแรกของ Khram และเป็นสีย้อมที่สตูดิโอใช้ตั้งชื่อ","สามองก์พาจากการสังเกต ไปสู่การเข้าใจ แล้วค่อยๆ เติบโต: The Deep Night, The Still Water และ The First Light ทุกหน้าคำถามมีหน้าว่างให้เขียนตามมาอีกหนึ่งหน้า"],"art":"พระจันทร์เต็มดวงเหนือทะเลสาบนิ่ง กับผีเสื้อสีฟ้าซีดหนึ่งตัว","statusNote":"พร้อมขาย"}}'::jsonb, 1)
on conflict (slug) do update set name = excluded.name, dye_thai = excluded.dye_thai, dye_english = excluded.dye_english, dye_note = excluded.dye_note, theme = excluded.theme, summary = excluded.summary, description = excluded.description, art = excluded.art, accent_base = excluded.accent_base, accent_text = excluded.accent_text, status = excluded.status, status_note = excluded.status_note, swatch = excluded.swatch, motif = excluded.motif, i18n = excluded.i18n, sort = excluded.sort;
insert into public.collections (slug, name, dye_thai, dye_english, dye_note, theme, summary, description, art, accent_base, accent_text, status, status_note, swatch, motif, i18n, sort)
values ('crimson', 'CRIMSON', 'ครั่ง', 'lac', 'Lac is a resin left on tree branches by a tiny insect. Boiled, it gives a deep red dye.', 'Love and attachment', 'For anxious attachment: the pull to check, the fear of being left, and learning to steady yourself.', array['CRIMSON is a workbook for anxious attachment. It explains what is happening when you can''t stop checking your phone, then gives you tools and prompts for when it happens.', 'It is being written and designed now. Contents may change before release.']::text[], 'One crimson thread across the night sky, a red-winged moth, and a moon half in shadow.', '#8E2A3A', '#C96B7A', 'in-progress', 'In the making', '{"src":"/images/swatches/crimson.webp","alt":"Cotton cloth dyed lac red, uneven where the dye soaked in.","width":900,"height":1125}'::jsonb, 'thread-moon', '{"th":{"dyeNote":"ครั่งคือยางที่แมลงตัวเล็กๆ สร้างไว้บนกิ่งไม้ นำมาต้มแล้วได้สีแดงเข้ม","theme":"ความรักและความผูกพัน","summary":"สำหรับคนที่ผูกพันแบบกังวล: อยากเช็คตลอด กลัวถูกทิ้ง และกำลังหัดทำใจให้นิ่ง","description":["CRIMSON คือเวิร์กบุ๊กสำหรับความผูกพันแบบกังวล อธิบายว่าเกิดอะไรขึ้นตอนที่เราหยุดเช็คโทรศัพท์ไม่ได้ แล้วให้เครื่องมือกับคำถามไว้ใช้ตอนที่มันเกิดขึ้น","ตอนนี้กำลังเขียนและออกแบบอยู่ เนื้อหาอาจเปลี่ยนก่อนวางขาย"],"art":"ด้ายสีแดงเส้นเดียวพาดผ่านท้องฟ้ากลางคืน ผีเสื้อกลางคืนปีกแดง และพระจันทร์ที่อยู่ในเงาครึ่งดวง","statusNote":"กำลังทำ"}}'::jsonb, 2)
