insert into public.products (slug, collection, name, format, subtitle, status, price, price_label, store, url, cta_label, notes, summary, description, included, included_heading, specs, how_it_works, outline, sample_prompts, faq, cover, gallery, og_image, i18n, published, sort)
values ('indigo-digital', 'indigo', 'INDIGO', 'Digital PDF', 'A Shadow Work & Emotional Healing Journal', 'available', 17.99, '$17.99', 'Gumroad', 'https://khramofficial.gumroad.com/l/shadow-work-journal', 'Buy on Gumroad', array['Instant download after purchase', '14-day money-back guarantee', 'Priced in US dollars. Gumroad shows your local currency at checkout.']::text[], '121 pages, 150+ prompts and a 30-night moon tracker, made for writing on an iPad or any tablet.', array['It''s 2 a.m. and your mind is replaying a conversation from three days ago. You said “I''m fine” again today. You keep saying yes when you mean no, then wonder why you feel so tired.', 'INDIGO is for people who feel deeply, think too much, and are done being told to “just stay positive.” No forced gratitude. No pretending. Just honest questions, quiet space, and room to understand the parts of yourself you learned to hide.']::text[], array['121 pages designed as one continuous journey', '150+ guided shadow work prompts across 50+ themed sessions', 'A full lined writing page after every prompt page', '30-day Indigo Moon Tracker: color one moon each night', 'A Letter to Your Younger Self and A Letter to Your Future Self', 'Affirmations you write in your own words', '“Before You Move Forward” check-ins at the end of each Act', 'A closing reflection and a written promise to yourself', 'Moonlit, impasto-style artwork on every page']::text[], null, '[{"label":"Format","value":"PDF, instant download"},{"label":"Pages","value":"121"},{"label":"Page size","value":"6.125 × 9.25 in"},{"label":"Prompts","value":"150+ across 50+ themed sessions"},{"label":"Works with","value":"GoodNotes, Notability, Noteshelf, Xodo, Samsung Notes and any PDF app"},{"label":"Links inside","value":"None. Pages are worked through in order."},{"label":"Language","value":"English"},{"label":"License","value":"Personal use"}]'::jsonb, array['Download the PDF right after purchase.', 'Import it into GoodNotes, Notability, Noteshelf, Xodo, Samsung Notes or any PDF annotation app.', 'Write in a light ink. White, gold or lavender shows up best on the indigo pages.', 'Go at your own pace. One prompt a day or one a week; there''s no wrong speed.']::text[], '{"heading":"Three Acts, one night at a time","items":[{"title":"Act I · The Deep Night","text":"Recognize. The emotions you hide, the fears you carry and the patterns you keep repeating. Prompts for overthinking, triggers, people-pleasing and your inner critic."},{"title":"Act II · The Still Water","text":"Understand. Gentle inner child work: the rules you learned growing up, the needs that went unmet, the boundaries you never got to set. Skip any memory that feels too heavy."},{"title":"Act III · The First Light","text":"Grow. Self-worth, a kinder inner voice, rest without guilt, and small promises you can actually keep."}]}'::jsonb, array['What have I been trying not to feel?', 'When do I say yes while wanting to say no?', 'What does this fear reveal about something I deeply value?', 'What did I learn about expressing sadness, anger, or fear?', 'What would progress look like if I measured it with patience rather than perfection?']::text[], '[{"q":"Is this a physical book?","a":"No. This edition is a digital PDF and nothing is shipped. For a printed copy, see the INDIGO paperback."},{"q":"What device do I need?","a":"A tablet with a stylus works best (iPad or Android). It also opens on any computer."},{"q":"Can I print it?","a":"Yes, for personal use. The pages have deep navy backgrounds, so printing uses a lot of ink and needs a white or metallic gel pen. The paperback is the easier way to write on paper."},{"q":"Is it hyperlinked?","a":"No. INDIGO is a page-by-page journey, meant to be worked through in order."}]'::jsonb, '{"src":"/images/products/indigo-paperback-cover.webp","alt":"INDIGO cover: a full moon over a still lake at night, a glowing pale-blue butterfly, wildflowers in the foreground, and the title INDIGO, A Shadow Work & Emotional Healing Journal, by Khram.","width":1000,"height":1499}'::jsonb, '[{"src":"/images/products/indigo-digital-hero.webp","alt":"The INDIGO digital journal: front cover beside two inside pages, The Indigo Journey and The Feelings I Hide.","width":1280,"height":720},{"src":"/images/products/indigo-inside.webp","alt":"Three pages from INDIGO: the 30 Days of Reflection moon tracker, The Feelings I Hide prompt page, and A Letter to My Younger Self with lined writing space.","width":1280,"height":720},{"src":"/images/products/indigo-thumb.webp","alt":"INDIGO digital journal cover with the full moon and pale-blue butterfly.","width":600,"height":600}]'::jsonb, '/images/og/indigo-digital.jpg', '{"th":{"format":"PDF ดิจิทัล","subtitle":"สมุดบันทึกสำรวจใจและเยียวยาอารมณ์","summary":"121 หน้า คำถามมากกว่า 150 ข้อ และตารางดวงจันทร์ 30 คืน ทำมาให้เขียนบน iPad หรือแท็บเล็ต","description":["ตีสองแล้ว แต่หัวยังเล่นบทสนทนาเมื่อสามวันก่อนซ้ำไปซ้ำมา วันนี้คุณพูดว่า “ไม่เป็นไร” อีกแล้ว คุณตอบตกลงทั้งที่อยากปฏิเสธ แล้วก็สงสัยว่าทำไมถึงเหนื่อยขนาดนี้","INDIGO ทำมาสำหรับคนที่รู้สึกลึก คิดเยอะ และเบื่อการถูกบอกให้ “คิดบวกเข้าไว้” ไม่ต้องฝืนขอบคุณ ไม่ต้องแกล้งทำเป็นโอเค มีแค่คำถามตรงๆ พื้นที่เงียบๆ และที่ว่างให้เข้าใจส่วนที่เราเคยซ่อนไว้"],"included":["121 หน้า ออกแบบให้เป็นการเดินทางต่อเนื่องเล่มเดียว","คำถามสำรวจใจมากกว่า 150 ข้อ ใน 50+ หัวข้อ","หน้าเส้นให้เขียนเต็มหน้าหลังทุกหน้าคำถาม","ตารางดวงจันทร์ 30 วัน ระบายคืนละดวง","จดหมายถึงตัวเองตอนเด็ก และจดหมายถึงตัวเองในอนาคต","ประโยคยืนยันที่เขียนด้วยคำของตัวเอง","เช็คอิน “Before You Move Forward” ท้ายทุกองก์","บทสะท้อนตอนจบ และคำสัญญาที่เขียนถึงตัวเอง","ภาพวาดสไตล์อิมพาสโตใต้แสงจันทร์ทุกหน้า"],"specs":[{"label":"รูปแบบ","value":"PDF ดาวน์โหลดได้ทันที"},{"label":"จำนวนหน้า","value":"121"},{"label":"ขนาดหน้า","value":"6.125 × 9.25 นิ้ว"},{"label":"คำถาม","value":"150+ ข้อ ใน 50+ หัวข้อ"},{"label":"ใช้กับ","value":"GoodNotes, Notability, Noteshelf, Xodo, Samsung Notes และแอป PDF ทั่วไป"},{"label":"ลิงก์ในเล่ม","value":"ไม่มี เขียนไปตามลำดับหน้า"},{"label":"ภาษาในเล่ม","value":"อังกฤษ"},{"label":"สิทธิ์การใช้","value":"ใช้ส่วนตัว"}],"howItWorks":["ดาวน์โหลด PDF ได้ทันทีหลังซื้อ","นำเข้าใน GoodNotes, Notability, Noteshelf, Xodo, Samsung Notes หรือแอปเขียน PDF ที่ใช้อยู่","ใช้หมึกสีอ่อน สีขาว ทอง หรือม่วงลาเวนเดอร์จะเห็นชัดบนหน้าสีคราม","ไปตามจังหวะของตัวเอง วันละคำถามหรือสัปดาห์ละคำถามก็ได้ ไม่มีความเร็วที่ผิด"],"outline":{"heading":"สามองก์ คืนละหนึ่งคำถาม","items":[{"title":"Act I · The Deep Night","text":"สังเกต ความรู้สึกที่ซ่อนไว้ ความกลัวที่แบกอยู่ และรูปแบบเดิมที่ทำซ้ำ มีคำถามเรื่องการคิดมาก สิ่งที่กระตุ้นอารมณ์ การเอาใจคนอื่น และเสียงวิจารณ์ในหัว"},{"title":"Act II · The Still Water","text":"เข้าใจ ดูแลเด็กในตัวเราอย่างอ่อนโยน: กฎที่เรียนมาตอนเด็ก ความต้องการที่ไม่เคยได้รับ และขอบเขตที่ไม่เคยได้ตั้ง ข้ามความทรงจำที่หนักเกินไปได้"},{"title":"Act III · The First Light","text":"เติบโต คุณค่าในตัวเอง เสียงในใจที่ใจดีขึ้น การพักโดยไม่รู้สึกผิด และสัญญาเล็กๆ ที่ทำได้จริง"}]},"faq":[{"q":"เป็นหนังสือเล่มจริงไหม","a":"ไม่ใช่ เล่มนี้เป็น PDF ดิจิทัล ไม่มีการจัดส่ง ถ้าอยากได้เล่มกระดาษ ดู INDIGO ฉบับพิมพ์"},{"q":"ต้องใช้อุปกรณ์อะไร","a":"แท็บเล็ตกับปากกาเหมาะที่สุด (iPad หรือ Android) เปิดบนคอมพิวเตอร์ได้ด้วย"},{"q":"พิมพ์ออกมาได้ไหม","a":"ได้ สำหรับใช้ส่วนตัว แต่พื้นหลังเป็นสีกรมท่าเข้ม จะเปลืองหมึกมาก และต้องใช้ปากกาเจลสีขาวหรือสีเมทัลลิก ถ้าอยากเขียนบนกระดาษ เล่มพิมพ์สะดวกกว่า"},{"q":"มีลิงก์ข้ามหน้าไหม","a":"ไม่มี INDIGO ออกแบบให้เขียนไปทีละหน้าตามลำดับ"}],"priceLabel":"$17.99","ctaLabel":"ซื้อที่ Gumroad","notes":["ดาวน์โหลดได้ทันทีหลังซื้อ","คืนเงินได้ภายใน 14 วัน","ราคาเป็นดอลลาร์สหรัฐ Gumroad จะแสดงเป็นเงินบาทตอนจ่ายเงิน"]}}'::jsonb, true, 1)
